<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { RefreshCw, Save } from 'lucide-vue-next'
import { useRoute } from 'vue-router'
import { getCapacityHistory, getLogisticsMonitoring, updateLogisticsConfig } from '../services/logisticsService'
import DemandAnalysisPanel from '../components/DemandAnalysisPanel.vue'
const route = useRoute(); const tab=ref(route.query.tab === 'analysis' ? 'analysis' : 'monitoring'), loading=ref(true), refreshing=ref(false), saving=ref(false), error=ref(''), notice=ref(''), monitor=ref({zones:[],config:null}), history=ref([]), historyLoading=ref(false), filters=reactive({zoneId:'',type:''}), form=reactive({umbral_advertencia:4,capacidad_maxima:5,umbral_reactivacion:4}); let timer
const summary=computed(()=>({available:monitor.value.zones.reduce((s,z)=>s+Number(z.disponibles||0),0),active:monitor.value.zones.reduce((s,z)=>s+Number(z.activos||0),0),operating:monitor.value.zones.filter(z=>z.activa).length,blocked:monitor.value.zones.filter(z=>z.activa&&z.bloqueada).length}))
function validate(){const w=Number(form.umbral_advertencia),m=Number(form.capacidad_maxima),r=Number(form.umbral_reactivacion);if(![w,m,r].every(v=>Number.isFinite(v)&&v>0))return'Todos los valores deben ser positivos.';if(r>w||w>=m)return'Debe cumplirse: reactivación ≤ advertencia < capacidad máxima.';return''}
function status(z){if(!z.activa)return['inactive','Inactiva'];if(z.bloqueada||!z.disponibles)return['blocked','Bloqueada'];if(z.advertencia)return['warning','Alta demanda'];return['normal','Operativa']}
async function load(silent=false){silent?refreshing.value=true:loading.value=true;try{monitor.value=await getLogisticsMonitoring();Object.assign(form,monitor.value.config||{});error.value=''}catch(e){error.value=e.message||'No se pudo cargar el monitoreo.'}finally{loading.value=false;refreshing.value=false}}
async function loadHistory(){historyLoading.value=true;try{history.value=await getCapacityHistory(filters)}catch(e){error.value=e.message||'No se pudo cargar el historial.'}finally{historyLoading.value=false}}
async function save(){error.value='';notice.value='';const v=validate();if(v){error.value=v;return};saving.value=true;try{Object.assign(form,await updateLogisticsConfig(form));notice.value='Configuración logística guardada.';await load(true)}catch(e){error.value=e.message||'No se pudo guardar la configuración.'}finally{saving.value=false}}
function selectTab(v){tab.value=v;if(v==='history')loadHistory()};function date(v){return new Date(v).toLocaleString('es-SV',{dateStyle:'short',timeStyle:'short'})}
onMounted(()=>{load();timer=setInterval(()=>load(true),10000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><section class="admin-view"><div class="admin-view-heading"><div><span class="admin-eyebrow">OPERACIÓN</span><h2>Control logístico</h2><p>Capacidad operativa y configuración de zonas.</p></div><button class="admin-icon-button" :disabled="refreshing" @click="load(true)"><RefreshCw :size="18" /></button></div><nav class="admin-tabs-inline"><button :class="{active:tab==='monitoring'}" @click="selectTab('monitoring')">Monitoreo</button><button :class="{active:tab==='configuration'}" @click="selectTab('configuration')">Configuración</button><button :class="{active:tab==='history'}" @click="selectTab('history')">Historial</button><button :class="{active:tab==='analysis'}" @click="selectTab('analysis')">Análisis de demanda</button></nav><p v-if="error" class="admin-alert">{{error}}</p><p v-if="notice" class="admin-success">{{notice}}</p><div v-if="loading" class="admin-empty">Cargando información…</div><template v-else-if="tab==='monitoring'"><div class="admin-stat-grid logistics-summary"><article class="admin-stat-card"><strong>{{summary.available}}</strong><small>Repartidores disponibles</small></article><article class="admin-stat-card"><strong>{{summary.active}}</strong><small>Pedidos activos</small></article><article class="admin-stat-card"><strong>{{summary.operating}}</strong><small>Zonas operativas</small></article><article class="admin-stat-card"><strong>{{summary.blocked}}</strong><small>Zonas bloqueadas</small></article></div><div class="admin-panel admin-table-wrap"><table class="admin-table"><thead><tr><th>Zona</th><th>Repartidores</th><th>Pedidos</th><th>Relación</th><th>Capacidad restante</th><th>Estado</th><th>Actualización</th></tr></thead><tbody><tr v-for="z in monitor.zones" :key="z.id"><td>{{z.nombre}}</td><td>{{z.disponibles}}</td><td>{{z.activos}}</td><td>{{z.disponibles?Number(z.ratio||0).toFixed(2):'—'}}</td><td>{{z.disponibles?Math.max(0,Number(form.capacidad_maxima)*z.disponibles-z.activos).toFixed(2):'—'}}</td><td><span class="logistics-status" :data-status="status(z)[0]">{{status(z)[1]}}</span><small v-if="z.bloqueada">{{z.disponibles?'Saturación':'Sin repartidores'}}</small></td><td>{{date(z.updated_at)}}</td></tr></tbody></table></div></template><form v-else-if="tab==='configuration'" class="admin-panel admin-form-grid" @submit.prevent="save"><label>Umbral de advertencia<input v-model.number="form.umbral_advertencia" type="number" min=".01" step=".01" required /></label><label>Capacidad máxima<input v-model.number="form.capacidad_maxima" type="number" min=".01" step=".01" required /></label><label>Umbral de reactivación<input v-model.number="form.umbral_reactivacion" type="number" min=".01" step=".01" required /></label><button class="admin-primary-button full" type="submit" :disabled="saving"><Save :size="17"/> {{saving?'Guardando…':'Guardar configuración'}}</button></form><DemandAnalysisPanel v-else-if="tab==='analysis'" :zones="monitor.zones" /><section v-else class="admin-panel"><div class="admin-toolbar"><select v-model="filters.zoneId" @change="loadHistory"><option value="">Todas las zonas</option><option v-for="z in monitor.zones" :key="z.id" :value="z.id">{{z.nombre}}</option></select><select v-model="filters.type" @change="loadHistory"><option value="">Todos los eventos</option><option value="BLOQUEO">Bloqueos</option><option value="REACTIVACION">Reactivaciones</option></select></div><div v-if="historyLoading" class="admin-empty">Cargando historial…</div><div v-else-if="!history.length" class="admin-empty">No hay eventos registrados.</div><table v-else class="admin-table"><thead><tr><th>Zona</th><th>Evento</th><th>Motivo</th><th>Relación</th><th>Fecha</th></tr></thead><tbody><tr v-for="e in history" :key="e.id"><td>{{e.zonas?.nombre||'—'}}</td><td>{{e.estado_nuevo?'Bloqueo':'Reactivación'}}</td><td>{{e.motivo}}</td><td>{{e.disponibles?`${Number(e.ratio||0).toFixed(2)} (${e.activos}/${e.disponibles})`:'Sin repartidores'}}</td><td>{{date(e.created_at)}}</td></tr></tbody></table></section></section></template>
